use knownext_storage::LocalApi;
use serde_json::{json,Value};
use std::{fs,path::{Path,PathBuf}};
fn call(api:&LocalApi,method:&str,path:&str,body:Value)->Value{let response=api.handle(method,path,body,vec![]).unwrap();assert!(response.status<400,"{}",response.body);response.body}
fn count(root:&Path)->usize{fs::read_dir(root.join("assets/handwritten")).unwrap().count()}
#[test]
fn handwritten_snapshots_never_replace_old_images_and_reject_changed_destinations_or_scope(){
 let owned=tempfile::tempdir().unwrap();let api=LocalApi::new(owned.path().join("state"),"qa".into(),"test".into());let project=call(&api,"POST","/api/projects",json!({"name":"Owned snapshots","versioningMode":"none","syncMode":"none"}));let root=PathBuf::from(project["folderPath"].as_str().unwrap());let p=project["id"].as_str().unwrap();let created=call(&api,"POST",&format!("/api/projects/{p}/handwritten-notes"),json!({"name":"boceto"}));let note=created["node"]["id"].as_str().unwrap();let loaded=call(&api,"GET",&format!("/api/handwritten-notes/{note}"),Value::Null);let source=fs::read(root.join("boceto.knote")).unwrap();let mut content=loaded["content"].clone();content["pages"][0]["id"]=json!("page1");content["pages"][0]["size"]["width"]=json!(128);content["pages"][0]["size"]["height"]=json!(128);content["pages"][0]["strokes"]=json!([{"id":"s1","tool":"pen","color":"#111827","width":4,"opacity":1,"points":[[10,10,0.5,0],[90,90,0.9,16]],"path":"M 10 10 L 90 90","bounds":{"x":8,"y":8,"width":84,"height":84}}]);
 fs::create_dir_all(root.join("assets/handwritten")).unwrap();let legacy=root.join("assets/handwritten/boceto-page1.png");fs::write(&legacy,b"owned legacy snapshot").unwrap();let markdown="# Plan\n\n![Anterior](assets/handwritten/boceto-page1.png)\n";let created=call(&api,"POST",&format!("/api/projects/{p}/documents"),json!({"name":"Plan.md","markdown":markdown}));let doc=created["node"]["id"].as_str().unwrap();let endpoint=format!("/api/handwritten-notes/{note}/pages/page1/insert-markdown");let first=call(&api,"POST",&endpoint,json!({"documentId":doc,"content":content,"altText":"Boceto"}));assert_eq!(first["snapshotReused"],false);let a=root.join(first["asset"]["path"].as_str().unwrap());let image_a=fs::read(&a).unwrap();assert!(image_a.starts_with(b"\x89PNG"));assert!(a.file_name().unwrap().to_string_lossy().contains(first["snapshotSha256"].as_str().unwrap()));let repeated=call(&api,"POST",&endpoint,json!({"documentId":doc,"content":content}));assert_eq!(repeated["snapshotReused"],true);assert_eq!(repeated["asset"]["path"],first["asset"]["path"]);assert_eq!(count(&root),2);
 let mut newer=content.clone();newer["pages"][0]["strokes"][0]["color"]=json!("#F37021");let second=call(&api,"POST",&endpoint,json!({"documentId":doc,"content":newer}));let b=root.join(second["asset"]["path"].as_str().unwrap());assert_ne!(a,b);assert_ne!(fs::read(&b).unwrap(),image_a);assert_eq!(fs::read(&a).unwrap(),image_a);assert_eq!(fs::read(&legacy).unwrap(),b"owned legacy snapshot");assert_eq!(count(&root),3);
 let permissions=fs::metadata(&b).unwrap().permissions();let mut readonly=permissions.clone();readonly.set_readonly(true);fs::set_permissions(&b,readonly).unwrap();let reused=api.handle("POST",&endpoint,json!({"documentId":doc,"content":newer}),vec![]);fs::set_permissions(&b,permissions).unwrap();assert_eq!(reused.unwrap().body["snapshotReused"],true);
 fs::write(&a,b"user changed image").unwrap();assert!(api.handle("POST",&endpoint,json!({"documentId":doc,"content":content}),vec![]).is_err());assert_eq!(fs::read(&a).unwrap(),b"user changed image");fs::write(&a,&image_a).unwrap();let other=call(&api,"POST","/api/projects",json!({"name":"Other scope","versioningMode":"none","syncMode":"none"}));let other_root=PathBuf::from(other["folderPath"].as_str().unwrap());assert!(api.handle("POST",&endpoint,json!({"documentId":format!("{}::Other.md",other["id"].as_str().unwrap()),"content":content}),vec![]).is_err());assert!(!other_root.join("assets").exists());let mut future=content.clone();future["schemaVersion"]=json!(99);assert!(api.handle("POST",&endpoint,json!({"documentId":doc,"content":future}),vec![]).is_err());assert!(api.handle("POST",&endpoint,json!({"documentId":format!("{p}::Missing.md"),"content":content}),vec![]).is_err());assert_eq!(count(&root),3);assert_eq!(fs::read(root.join("boceto.knote")).unwrap(),source);assert_eq!(fs::read(root.join("Plan.md")).unwrap(),markdown.as_bytes());assert_eq!(fs::read(&legacy).unwrap(),b"owned legacy snapshot");assert_eq!(fs::read(&a).unwrap(),image_a);
}
